def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    stencil = [[not bool(grid[r][c]) for c in range(w)] for r in range(h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr in range(h):
                    for dc in range(w):
                        if stencil[dr][dc]:
                            out[h * r + dr][w * c + dc] = value
    return out
